{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "description": "Each object SAM 3 followed through the walk, a bar in its label's lane from when it was first seen to when it was last seen: in its label's color once the video has played past its first sighting, gray before. The bar's outline keeps an object seen in one frame alone in view.",
  "mark": {
    "type": "bar",
    "strokeWidth": 2
  },
  "encoding": {
    "y": {
      "field": "label",
      "type": "nominal",
      "title": null
    },
    "x": {
      "field": "start_s",
      "type": "quantitative",
      "title": "Seconds into the walk"
    },
    "x2": {
      "field": "end_s"
    },
    "color": {
      "condition": {
        "test": "datum.interacted === '1'",
        "field": "label",
        "type": "nominal",
        "legend": null
      },
      "value": "#c8c8c8"
    },
    "stroke": {
      "condition": {
        "test": "datum.interacted === '1'",
        "field": "label",
        "type": "nominal",
        "legend": null
      },
      "value": "#c8c8c8"
    },
    "tooltip": [
      {
        "field": "label",
        "type": "nominal"
      },
      {
        "field": "object_id",
        "type": "quantitative",
        "title": "object"
      },
      {
        "field": "start_s",
        "type": "quantitative",
        "title": "first seen (s)"
      },
      {
        "field": "end_s",
        "type": "quantitative",
        "title": "last seen (s)"
      },
      {
        "field": "frames",
        "type": "quantitative"
      }
    ]
  }
}
